    # Sort to find the rectangle corners
    points.sort()
    r1, c1, v_tl = points[0]  # top-left
    r2, c2, v_tr = points[1]  # top-right
    r3, c3, v_bl = points[2]  # bottom-left
    r4, c4, v_br = points[3]  # bottom-right

    out = [[0]*cols for _ in range(rows)]

